          return;
        }
        const filter = taskFilter(form.get('filter'));
        const taskId = taskRoute[2];
        if (taskId) {
          let result;
          if (taskRoute[3] === 'rename') {
            const title = (form.get('title') ?? '').trim();
            if (!title) {
              sendHtml(response, 400, projectPage(project, filter, 'Task title is required'));
              return;
            }
            result = renameTask.run(title, taskId, project.id);
          } else if (taskRoute[3] === 'priority') {
            const priority = form.get('priority');
            if (!taskPriorities.includes(priority)) {
              sendHtml(response, 400, projectPage(project, filter, 'Invalid task priority'));
              return;
            }
            result = setTaskPriority.run(priority, taskId, project.id);
          } else {
            result = updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, project.id);
          }
          if (!result.changes) {
            sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
            return;
          }
        } else {
          const title = (form.get('title') ?? '').trim();
          if (!title) {
            sendHtml(response, 400, projectPage(project, filter, 'Task title is required'));
            return;
          }
          addTask.run(project.id, title);
        }
        redirect(response, projectPath(project.id, filter));
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Page not found</h1><a href="/">Projects</a>'));
  } catch (error) {
    console.error(error);
    sendHtml(response, 500, page('Error', '<h1>Something went wrong</h1><a href="/">Projects</a>'));
  }
});

